        private void txtIcdCode1_Validating(object sender, CancelEventArgs e)
        {
            try
            {
                string search = ((TextEdit)sender).Text;
                if (!string.IsNullOrEmpty(search))
                {
                    List<HIS_ICD> list = dataIcds.Where((HIS_ICD o) => o.ICD_CODE.Contains(search)).ToList();
                    List<HIS_ICD> list2 = ((list == null) ? null : ((list.Count > 1) ? list.Where((HIS_ICD o) => o.ICD_CODE == search).ToList() : list));
                    if (list2 == null || list2.Count <= 0)
                    {
                        e.Cancel = true;
                        return;
                    }
                    txtIcdCode1.ErrorText = "";
                    dxValidationProvider1.RemoveControlError(txtIcdCode1);
                    ValidationICD(10, 500, true, txtIcdCode1, txtIcd1, cboIcd1, chkIcd1, lciIcd1);
                }
            }
            catch (Exception ex)
            {
                LogSystem.Error(ex);
            }
        }

