                ControlEditorADO controlEditorADO = new ControlEditorADO("USERNAME", "LOGINNAME", new List<ColumnInfo>
				{
					new ColumnInfo("LOGINNAME", "Tên đăng nhập", 150, 1),
					new ColumnInfo("USERNAME", "Họ tên", 250, 2)
