                Action myaction = delegate
                {
                    long DepartmentID = WorkPlace.WorkPlaceSDO.FirstOrDefault((WorkPlaceSDO o) => o.RoomId == this.Module.RoomId).DepartmentId;
                    string loginname = ClientTokenManagerStore.ClientTokenManager.GetLoginName();
                    ptttTemp = (from o in BackendDataWorker.Get<HIS_SERE_SERV_PTTT_TEMP>()
                                where o.IS_ACTIVE == 1 && (o.IS_PUBLIC == 1 || (o.IS_PUBLIC_IN_DEPARTMENT == 1 && o.DEPARTMENT_ID == DepartmentID) || o.CREATOR == loginname)
                                select o).ToList();
                };
                Task task = new Task(myaction);
                task.Start();
                await task;
                ControlEditorADO controlEditorADO = new ControlEditorADO("SERE_SERV_PTTT_TEMP_NAME", "ID", new List<ColumnInfo>
				{
					new ColumnInfo("SERE_SERV_PTTT_TEMP_CODE", "", 150, 1),
					new ColumnInfo("SERE_SERV_PTTT_TEMP_NAME", "", 250, 2)
				}, false, 400);
                controlEditorADO.ImmediatePopup = true;
                ControlEditorLoader.Load((object)cboPtttTemp, (object)ptttTemp, controlEditorADO);
            }
            catch (Exception ex)
            {
                Exception ex2 = ex;
                LogSystem.Warn(ex2);
            }
        }

