        private async Task LoadSereServExt()
        {
            try
            {
                CommonParam param = new CommonParam();
                HisSereServExtFilter ssExtFilter = new HisSereServExtFilter();
                ssExtFilter.SERE_SERV_IDs = new List<long> { sereServ.ID };
                if (dicSereServCopy != null && dicSereServCopy.Count > 0 && dicSereServCopy.ContainsKey(sereServ.ID))
                {
                    ssExtFilter.SERE_SERV_IDs.Add(dicSereServCopy[sereServ.ID]);
                }
                List<HIS_SERE_SERV_EXT> SereServExts = await ((AdapterBase)new BackendAdapter(param)).GetAsync<List<HIS_SERE_SERV_EXT>>("api/HisSereServExt/Get", HIS.Desktop.ApiConsumer.ApiConsumers.MosConsumer, (object)ssExtFilter, param);
                SereServExt = new HIS_SERE_SERV_EXT();
                if (SereServExts != null && SereServExts.Count > 0)
                {
                    foreach (HIS_SERE_SERV_EXT item in ListSereServExt)
                    {
                        HIS_SERE_SERV_EXT ext = ListSereServExt.FirstOrDefault((HIS_SERE_SERV_EXT o) => o.ID == item.ID);
                        if (ext != null)
                        {
                            HIS_SERE_SERV_EXT val = item;
                        }
                        else
                        {
                            ListSereServExt.Add(item);
                        }
                    }
                    HIS_SERE_SERV_EXT dfSereServExt = SereServExts.FirstOrDefault((HIS_SERE_SERV_EXT o) => o.SERE_SERV_ID == sereServ.ID);
                    if (dicSereServCopy != null && dicSereServCopy.Count > 0 && dicSereServCopy.ContainsKey(sereServ.ID))
                    {
                        SereServExt = SereServExts.FirstOrDefault((HIS_SERE_SERV_EXT o) => o.SERE_SERV_ID == dicSereServCopy[sereServ.ID]);
                    }
                    else
                    {
                        SereServExt = dfSereServExt;
                    }
                    txtConclude.Text = SereServExt.CONCLUDE;
                    txtDescription.Text = SereServExt.DESCRIPTION;
                    txtResultNote.Text = SereServExt.NOTE;
                    txtIntructionNote.Text = ((!string.IsNullOrEmpty(SereServExt.INSTRUCTION_NOTE) || !txtIntructionNote.Text.Equals(SereServExt.INSTRUCTION_NOTE)) ? SereServExt.INSTRUCTION_NOTE : dfSereServExt.INSTRUCTION_NOTE);
                    txtMachineCode.Text = SereServExt.MACHINE_CODE;
                    cboMachine.EditValue = SereServExt.MACHINE_ID;
                    LogSystem.Info("SereServExts: " + SereServExts.Count);
                    if (SereServExt.BEGIN_TIME.HasValue)
                    {
                        DateTime dt = Inventec.Common.DateTime.Convert.TimeNumberToSystemDateTime(SereServExt.BEGIN_TIME.Value) ?? DateTime.Now;
                        dtStart.DateTime = new DateTime(dt.Year, dt.Month, dt.Day, dt.Hour, dt.Minute, 0);
                    }
                    else
                    {
                        dtStart.EditValue = null;
                    }
                    if (SereServExt.END_TIME.HasValue)
                    {
                        DateTime dt2 = Inventec.Common.DateTime.Convert.TimeNumberToSystemDateTime(SereServExt.END_TIME.Value) ?? DateTime.Now;
                        dtFinish.DateTime = new DateTime(dt2.Year, dt2.Month, dt2.Day, dt2.Hour, dt2.Minute, 0);
                        dtFinish.Properties.Buttons[1].Visible = true;
                        if (SereServExt.BEGIN_TIME.HasValue)
                        {
                            DateTime? dateBefore = Inventec.Common.DateTime.Convert.TimeNumberToSystemDateTime(SereServExt.BEGIN_TIME.Value);
                            DateTime? dateAfter = Inventec.Common.DateTime.Convert.TimeNumberToSystemDateTime(SereServExt.END_TIME.Value);
                            if (dateBefore.HasValue && dateAfter.HasValue)
                            {
                                TimeSpan difference = dateAfter.Value - dateBefore.Value;
                                TimeSpan timeSpan = difference;
                                LogSystem.Warn(timeSpan.ToString() + "_______________!!!!");
                                spinExcuteTimeAdd.EditValue = difference.TotalMinutes;
                            }
                        }
                    }
                    else
                    {
                        dtFinish.EditValue = null;
                        dtFinish.Properties.Buttons[1].Visible = false;
                    }
                }
                else
                {
                    txtConclude.Text = "";
                    txtDescription.Text = "";
                    txtResultNote.Text = "";
                    txtIntructionNote.Text = "";
                    txtMachineCode.Text = "";
                    cboMachine.EditValue = null;
                }
                if (!string.IsNullOrWhiteSpace(HisConfigCFG.TAKE_INTRUCTION_TIME_BY_SERVICE_REQ) && (SereServExt == null || !SereServExt.BEGIN_TIME.HasValue))
                {
                    if (serviceReq != null && sereServ.TDL_SERVICE_TYPE_ID == 4 && HisConfigCFG.TAKE_INTRUCTION_TIME_BY_SERVICE_REQ == "1")
                    {
                        dtStart.DateTime = Inventec.Common.DateTime.Convert.TimeNumberToSystemDateTime(serviceReq.INTRUCTION_TIME) ?? DateTime.Now;
                    }
                    else if (serviceReq != null && (sereServ.TDL_SERVICE_TYPE_ID == 4 || sereServ.TDL_SERVICE_TYPE_ID == 11) && HisConfigCFG.TAKE_INTRUCTION_TIME_BY_SERVICE_REQ == "2")
                    {
                        dtStart.DateTime = Inventec.Common.DateTime.Convert.TimeNumberToSystemDateTime(serviceReq.INTRUCTION_TIME) ?? DateTime.Now;
                    }
                    else if (serviceReq != null && (sereServ.TDL_SERVICE_TYPE_ID == 4 || sereServ.TDL_SERVICE_TYPE_ID == 11) && HisConfigCFG.TAKE_INTRUCTION_TIME_BY_SERVICE_REQ == "3")
                    {
                        dtStart.DateTime = DateTime.Now;
                    }
                }
                if (spinExcuteTimeAdd.EditValue != null && spinExcuteTimeAdd.Value > 0m && dtStart.DateTime != DateTime.MinValue && (SereServExt == null || !SereServExt.END_TIME.HasValue))
                {
                    dtFinish.DateTime = dtStart.DateTime.AddMinutes((double)spinExcuteTimeAdd.Value);
                }
                InitButtonOther();
                List<long> ssIds = new List<long>();
                if (dicSereServCopy != null && dicSereServCopy.Count > 0 && dicSereServCopy.ContainsKey(sereServ.ID))
                {
                    ssIds.Add(dicSereServCopy[sereServ.ID]);
                }
                else
                {
                    ssIds.Add(sereServ.ID);
                }
                ProcessLoadSereServFile(ssIds);
            }
            catch (Exception ex)
            {
                Exception ex2 = ex;
                LogSystem.Warn(ex2);
            }
        }

        private bool CheckLessTime(ref string serviceCode)
        {
            //IL_002b: Unknown result type (might be due to invalid IL or missing references)
            //IL_0031: Expected O, but got Unknown
            //IL_0031: Unknown result type (might be due to invalid IL or missing references)
            //IL_0038: Expected O, but got Unknown
            //IL_0071: Unknown result type (might be due to invalid IL or missing references)
            bool result = false;
            try
            {
                if (sereServbyServiceReqs != null && sereServbyServiceReqs.Count > 0)
                {
                    CommonParam val = new CommonParam();
                    HisSereServExtFilter val2 = new HisSereServExtFilter();
                    val2.SERE_SERV_IDs = sereServbyServiceReqs.Select((V_HIS_SERE_SERV_5 o) => o.ID).ToList();
                    List<HIS_SERE_SERV_EXT> rsApi = ((AdapterBase)new BackendAdapter(val)).Get<List<HIS_SERE_SERV_EXT>>("api/HisSereServExt/Get", HIS.Desktop.ApiConsumer.ApiConsumers.MosConsumer, (object)val2, val);
                    if (rsApi != null && rsApi.Count > 0)
                    {
                        if (rsApi.Count == sereServbyServiceReqs.Count)
                        {
                            List<HIS_SERE_SERV_EXT> check = rsApi.Where((HIS_SERE_SERV_EXT o) => !o.BEGIN_TIME.HasValue || !o.END_TIME.HasValue).ToList();
                            if (check != null && check.Count > 0)
                            {
                                result = true;
                                serviceCode = string.Join(",", (from o in sereServbyServiceReqs
                                                                where check.Select((HIS_SERE_SERV_EXT p) => p.SERE_SERV_ID).Contains(o.ID)
                                                                select o.TDL_SERVICE_CODE).ToList());
                            }
                        }
                        else if (rsApi.Count < sereServbyServiceReqs.Count)
                        {
                            result = true;
                            serviceCode = string.Join(",", (from o in sereServbyServiceReqs
                                                            where !rsApi.Select((HIS_SERE_SERV_EXT p) => p.SERE_SERV_ID).Contains(o.ID)
                                                            select o.TDL_SERVICE_CODE).ToList());
                        }
                    }
                    else
                    {
                        result = true;
                        serviceCode = string.Join(",", sereServbyServiceReqs.Select((V_HIS_SERE_SERV_5 o) => o.TDL_SERVICE_CODE).ToList());
                    }
                }
            }
            catch (Exception ex)
            {
                LogSystem.Warn(ex);
                return false;
            }
            return result;
        }

