        private bool ProcessLoadSereServFile(List<long> sereServId)
        {
            bool result = false;
            try
            {
                List<HIS_SERE_SERV_FILE> sereServFilesBySereServId = GetSereServFilesBySereServId(sereServId);
                if (sereServFilesBySereServId != null && sereServFilesBySereServId.Count > 0)
                {
                    result = true;
                    imageADOs = new List<ImageADO>();
                    foreach (HIS_SERE_SERV_FILE item in sereServFilesBySereServId)
                    {
                        LogSystem.Debug(LogUtil.TraceData("item.URL", (object)item.URL) + "____" + LogUtil.TraceData(LogUtil.GetMemberName<List<long>>((Expression<Func<List<long>>>)(() => sereServId)), (object)sereServId));
                        MemoryStream file = FileDownload.GetFile(item.URL);
                        if (file != null && file.Length > 0)
                        {
                            ImageADO imageADO = new ImageADO();
                            DataObjectMapper.Map<HIS_SERE_SERV_FILE>((object)imageADO, (object)item);
                            imageADO.FileName = item.SERE_SERV_FILE_NAME + DateTime.Now.ToString("yyyyMMddHHmmssfff");
                            imageADO.IsChecked = false;
                            imageADO.streamImage = new MemoryStream();
                            file.Position = 0L;
                            file.CopyTo(imageADO.streamImage);
                            file.Position = 0L;
                            imageADO.IMAGE_DISPLAY = Image.FromStream(file);
                            imageADOs.Add(imageADO);
                        }
                    }
                    ProcessLoadGridImage(imageADOs);
                }
                else
                {
                    cardControl.DataSource = null;
                    imageADOs = null;
                }
            }
            catch (Exception ex)
            {
                result = false;
                LogSystem.Error(ex);
            }
            return result;
        }

