        private bool ValidateHisService_MaxTotalProcessTime(bool notShowMess)
        {
            bool result = true;
            try
            {
                if (HisConfigCFG.PROCESS_TIME_MUST_BE_LESS_THAN_MAX_TOTAL_PROCESS_TIME != "1" && HisConfigCFG.PROCESS_TIME_MUST_BE_LESS_THAN_MAX_TOTAL_PROCESS_TIME != "2")
                {
                    return result;
                }
                DateTime? dateTime = Inventec.Common.DateTime.Convert.TimeNumberToSystemDateTime(serviceReq.INTRUCTION_TIME);
                if (!dateTime.HasValue)
                {
                    return result;
                }
                DateTime dateTime2 = dateTime.Value.AddSeconds(-dateTime.Value.Second);
                TimeSpan timeSpan = dtFinish.DateTime - dateTime2;
                Dictionary<long, List<V_HIS_SERVICE>> dictionary = new Dictionary<long, List<V_HIS_SERVICE>>();
                if (chkSaveGroup.Checked)
                {
                    if (sereServbyServiceReqs == null)
                    {
                        return result;
                    }
                    foreach (V_HIS_SERE_SERV_5 item in sereServbyServiceReqs)
                    {
                        V_HIS_SERVICE val = lstService.FirstOrDefault((V_HIS_SERVICE o) => o.ID == item.SERVICE_ID);
                        if (val == null || !val.MAX_TOTAL_PROCESS_TIME.HasValue || val.MAX_TOTAL_PROCESS_TIME.Value <= 0 || !(timeSpan.TotalMinutes > (double)val.MAX_TOTAL_PROCESS_TIME.Value) || (!string.IsNullOrEmpty(val.TOTAL_TIME_EXCEPT_PATY_IDS) && ("," + val.TOTAL_TIME_EXCEPT_PATY_IDS + ",").Contains("," + item.PATIENT_TYPE_ID + ",")))
                        {
                            continue;
                        }
                        if (dictionary.ContainsKey(val.MAX_TOTAL_PROCESS_TIME.Value))
                        {
                            if (!dictionary[val.MAX_TOTAL_PROCESS_TIME.Value].Contains(val))
                            {
                                dictionary[val.MAX_TOTAL_PROCESS_TIME.Value].Add(val);
                            }
                        }
                        else
                        {
                            dictionary.Add(val.MAX_TOTAL_PROCESS_TIME.Value, new List<V_HIS_SERVICE> { val });
                        }
                    }
                }
                else
                {
                    V_HIS_SERVICE val2 = lstService.FirstOrDefault((V_HIS_SERVICE o) => o.ID == sereServ.SERVICE_ID);
                    if (val2 != null && val2.MAX_TOTAL_PROCESS_TIME.HasValue && val2.MAX_TOTAL_PROCESS_TIME.Value > 0 && timeSpan.TotalMinutes > (double)val2.MAX_TOTAL_PROCESS_TIME.Value && (string.IsNullOrEmpty(val2.TOTAL_TIME_EXCEPT_PATY_IDS) || !("," + val2.TOTAL_TIME_EXCEPT_PATY_IDS + ",").Contains("," + sereServ.PATIENT_TYPE_ID + ",")))
                    {
                        dictionary.Add(val2.MAX_TOTAL_PROCESS_TIME.Value, new List<V_HIS_SERVICE> { val2 });
                    }
                }
                LogSystem.Debug(LogUtil.TraceData("dicInvalidServices", (object)dictionary));
                if (dictionary.Count > 0)
                {
                    string text = "";
                    List<string> list = new List<string>();
                    if (HisConfigCFG.PROCESS_TIME_MUST_BE_LESS_THAN_MAX_TOTAL_PROCESS_TIME == "1")
                    {
                        foreach (KeyValuePair<long, List<V_HIS_SERVICE>> item4 in dictionary)
                        {
                            string item2 = string.Format(ResourceMessage.KhongChoPhepTraKetQuaDichVu_Sau_PhutTinhTuThoiDiemRaYLenh, string.Join(", ", item4.Value.Select((V_HIS_SERVICE o) => o.SERVICE_NAME)), item4.Key.ToString(), Inventec.Common.DateTime.Convert.TimeNumberToTimeString(serviceReq.INTRUCTION_TIME));
                            list.Add(item2);
                        }
                        text = string.Join("; ", list) + ".";
                        if (notShowMess)
                        {
                            LogSystem.Info(text);
                            return true;
                        }
                        result = false;
                        XtraMessageBox.Show(text, ResourceMessage.ThongBao, MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
                    }
                    else if (HisConfigCFG.PROCESS_TIME_MUST_BE_LESS_THAN_MAX_TOTAL_PROCESS_TIME == "2")
                    {
                        foreach (KeyValuePair<long, List<V_HIS_SERVICE>> item5 in dictionary)
                        {
                            string item3 = string.Format(ResourceMessage.TraKetQuaDichVu_VuotQua_PhutTinhTuThoiDiemRaYLenh, string.Join(", ", item5.Value.Select((V_HIS_SERVICE o) => o.SERVICE_NAME)), item5.Key.ToString(), Inventec.Common.DateTime.Convert.TimeNumberToTimeString(serviceReq.INTRUCTION_TIME));
                            list.Add(item3);
                        }
                        text = string.Join("; ", list) + ".";
                        if (notShowMess)
                        {
                            LogSystem.Info(text);
                            return true;
                        }
                        if (XtraMessageBox.Show(string.Format("{0} {1}", text, ResourceMessage.BanCoMuonTiepTucKhong), ResourceMessage.ThongBao, MessageBoxButtons.YesNo, MessageBoxIcon.Exclamation) != DialogResult.Yes)
                        {
                            result = false;
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                LogSystem.Error(ex);
            }
            return result;
        }

