            try
            {
                List<HisEkipUserADO> dataSource = ucEkip.GetDataSource();
                dataSource.ForEach(delegate(HisEkipUserADO o)
                {
                    o.Action = 2;
                });
                dataSource.LastOrDefault().Action = 1;
                if ((dataSource.Where((HisEkipUserADO o) => string.IsNullOrEmpty(((V_HIS_EKIP_USER)o).LOGINNAME) || ((V_HIS_EKIP_USER)o).EXECUTE_ROLE_ID <= 0).FirstOrDefault() != null) ? true : false)
                {
                    MessageBox.Show(ResourceMessage.VuiLongNhapThongTinkipThucHien);
                    return;
                }
                List<IGrouping<string, HisEkipUserADO>> list = (from o in dataSource
                                                                where !string.IsNullOrWhiteSpace(((V_HIS_EKIP_USER)o).LOGINNAME)
                                                                group o by ((V_HIS_EKIP_USER)o).LOGINNAME).ToList();
                if (list != null && list.Count > 0)
                {
                    List<string> list2 = new List<string>();
                    foreach (IGrouping<string, HisEkipUserADO> item in list)
                    {
                        if (item.Count() <= 1)
                        {
                            continue;
                        }
                        List<HIS_EXECUTE_ROLE> source = (from o in BackendDataWorker.Get<HIS_EXECUTE_ROLE>()
                                                         where item.Select((HisEkipUserADO s) => ((V_HIS_EKIP_USER)s).EXECUTE_ROLE_ID).Contains(o.ID)
                                                         select o).ToList();
                        list2.Add(string.Format("Tài khoản {0} được thiết lập với các vai trò {1}", item.Key, string.Join(",", source.Select((HIS_EXECUTE_ROLE s) => s.EXECUTE_ROLE_NAME))));
                    }
                    if (list2.Count > 0)
                    {
                        XtraMessageBox.Show(string.Join("\n", list2), ResourceMessage.ThongBao);
                        return;
                    }
                }
                frmEkipTemp frmEkipTemp = new frmEkipTemp(dataSource, new DelegateRefreshData(RefeshDataEkipTemp), this.Module);
                frmEkipTemp.ShowDialog();
            }
            catch (Exception ex)
            {
                LogSystem.Warn(ex);
            }
        }

