        private string processIcdNameChanged(string oldIcdNames, string newIcdNames)
        {
            string text = "";
            try
            {
                text = newIcdNames;
                if (!string.IsNullOrEmpty(oldIcdNames))
                {
                    string[] array = oldIcdNames.Split(new string[1] { ";" }, StringSplitOptions.RemoveEmptyEntries);
                    if (array != null && array.Length != 0)
                    {
                        string[] array2 = array;
                        foreach (string item in array2)
                        {
                            if (!string.IsNullOrEmpty(item) && !newIcdNames.Contains(IcdUtil.AddSeperateToKey(item)))
                            {
                                HIS_ICD val = (from o in BackendDataWorker.Get<HIS_ICD>()
                                               where IcdUtil.AddSeperateToKey(item).Equals(IcdUtil.AddSeperateToKey(o.ICD_NAME))
                                               select o).FirstOrDefault();
                                if (val == null || val.ID == 0)
                                {
                                    text = text + item + ";";
                                }
                            }
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                LogSystem.Warn(ex);
            }
            return text;
        }

        private string processIcdCmNameChanged(string oldIcdNames, string newIcdNames)
        {
            string text = "";
            try
            {
                text = newIcdNames;
                if (!string.IsNullOrEmpty(oldIcdNames))
                {
                    string[] array = oldIcdNames.Split(new string[1] { ";" }, StringSplitOptions.RemoveEmptyEntries);
                    if (array != null && array.Length != 0)
                    {
                        string[] array2 = array;
                        foreach (string item in array2)
                        {
                            if (!string.IsNullOrEmpty(item) && !newIcdNames.Contains(IcdUtil.AddSeperateToKey(item)))
                            {
                                HIS_ICD_CM val = (from o in BackendDataWorker.Get<HIS_ICD_CM>()
                                                  where IcdUtil.AddSeperateToKey(item).Equals(IcdUtil.AddSeperateToKey(o.ICD_CM_NAME))
                                                  select o).FirstOrDefault();
                                if (val == null || val.ID == 0)
                                {
                                    text = text + item + ";";
                                }
                            }
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                LogSystem.Warn(ex);
            }
            return text;
        }

        private void dxValidationProvider1_ValidationFailed(object sender, ValidationFailedEventArgs e)
        {
            try
            {
                BaseEdit baseEdit = e.InvalidControl as BaseEdit;
                if (baseEdit == null)
                {
                    return;
                }
                BaseEditViewInfo baseEditViewInfo = baseEdit.GetViewInfo() as BaseEditViewInfo;
                if (baseEditViewInfo == null)
                {
                    return;
                }
                if (positionHandle == -1)
                {
                    positionHandle = baseEdit.TabIndex;
                    if (baseEdit.Visible)
                    {
                        baseEdit.SelectAll();
                        baseEdit.Focus();
                    }
                }
                if (positionHandle > baseEdit.TabIndex)
                {
                    positionHandle = baseEdit.TabIndex;
                    if (baseEdit.Visible)
                    {
                        baseEdit.SelectAll();
                        baseEdit.Focus();
                    }
                }
            }
