                {
                    val.TDL_SERVICE_CODE = val2.SERVICE_CODE;
                    val.TDL_SERVICE_NAME = val2.SERVICE_NAME;
                    val.SERVICE_UNIT_NAME = val2.SERVICE_UNIT_NAME;
                    val.TDL_SERVICE_TYPE_ID = val2.SERVICE_TYPE_ID;
