        private async Task FillDataFromSereServLast(long id)
        {
            try
            {
                CommonParam param = new CommonParam();
                HisSereServExtFilter ssExtFilter = new HisSereServExtFilter();
                ssExtFilter.SERE_SERV_ID = id;
                List<HIS_SERE_SERV_EXT> SereServExts = await ((AdapterBase)new BackendAdapter(param)).GetAsync<List<HIS_SERE_SERV_EXT>>("api/HisSereServExt/Get", HIS.Desktop.ApiConsumer.ApiConsumers.MosConsumer, (object)ssExtFilter, param);
                SereServExt = new HIS_SERE_SERV_EXT();
                if (SereServExts != null && SereServExts.Count > 0)
                {
                    foreach (HIS_SERE_SERV_EXT item in ListSereServExt)
                    {
                        HIS_SERE_SERV_EXT ext = ListSereServExt.FirstOrDefault((HIS_SERE_SERV_EXT o) => o.ID == item.ID);
                        if (ext != null)
                        {
                            HIS_SERE_SERV_EXT val = item;
                        }
                        else
                        {
                            ListSereServExt.Add(item);
                        }
                    }
                    SereServExt = SereServExts.FirstOrDefault();
                    txtConclude.Text = SereServExt.CONCLUDE;
                    txtDescription.Text = SereServExt.DESCRIPTION;
                    txtResultNote.Text = SereServExt.NOTE;
                    txtIntructionNote.Text = SereServExt.INSTRUCTION_NOTE;
                    txtMachineCode.Text = SereServExt.MACHINE_CODE;
                    cboMachine.EditValue = SereServExt.MACHINE_ID;
                    LogSystem.Info("SereServExts: " + SereServExts.Count);
                    dtStart.DateTime = DateTime.Now;
                    dtFinish.DateTime = DateTime.Now;
                }
                else
                {
                    txtConclude.Text = "";
                    txtDescription.Text = "";
                    txtResultNote.Text = "";
                    txtIntructionNote.Text = "";
                    txtMachineCode.Text = "";
                    cboMachine.EditValue = null;
                }
                if (!string.IsNullOrWhiteSpace(HisConfigCFG.TAKE_INTRUCTION_TIME_BY_SERVICE_REQ) && (SereServExt == null || !SereServExt.BEGIN_TIME.HasValue))
                {
                    if (serviceReq != null && sereServ.TDL_SERVICE_TYPE_ID == 4 && HisConfigCFG.TAKE_INTRUCTION_TIME_BY_SERVICE_REQ == "1")
                    {
                        dtStart.DateTime = Inventec.Common.DateTime.Convert.TimeNumberToSystemDateTime(serviceReq.INTRUCTION_TIME) ?? DateTime.Now;
                    }
                    else if (serviceReq != null && (sereServ.TDL_SERVICE_TYPE_ID == 4 || sereServ.TDL_SERVICE_TYPE_ID == 11) && HisConfigCFG.TAKE_INTRUCTION_TIME_BY_SERVICE_REQ == "2")
                    {
                        dtStart.DateTime = Inventec.Common.DateTime.Convert.TimeNumberToSystemDateTime(serviceReq.INTRUCTION_TIME) ?? DateTime.Now;
                    }
                    else if (serviceReq != null && (sereServ.TDL_SERVICE_TYPE_ID == 4 || sereServ.TDL_SERVICE_TYPE_ID == 11) && HisConfigCFG.TAKE_INTRUCTION_TIME_BY_SERVICE_REQ == "3")
                    {
                        dtStart.DateTime = DateTime.Now;
                    }
                }
                if (spinExcuteTimeAdd.EditValue != null && spinExcuteTimeAdd.Value > 0m && dtStart.DateTime != DateTime.MinValue && (SereServExt == null || !SereServExt.END_TIME.HasValue))
                {
                    dtFinish.DateTime = dtStart.DateTime.AddMinutes((double)spinExcuteTimeAdd.Value);
                }
                InitButtonOther();
                ProcessLoadSereServFile(new List<long> { sereServ.ID });
            }
            catch (Exception ex)
            {
                Exception ex2 = ex;
                LogSystem.Warn(ex2);
            }
        }

