                        DataObjectMapper.Map<V_HIS_SERE_SERV_5>((object)val2, (object)val);
                        val2.SERVICE_UNIT_NAME = item.SERVICE_UNIT_NAME;
                        val2.TDL_TREATMENT_ID = item.TDL_TREATMENT_ID;
                        val2.ID = item.ID;
                        val2.SERVICE_REQ_ID = item.SERVICE_REQ_ID;
                        if (!dicSereServCopy.ContainsKey(item.ID))
                        {
                            dicSereServCopy[item.ID] = val.ID;
                        }
                        list.Add(val2);
                    }
                    else
                    {
                        list.Add(item);
                    }
                }
                grdControlService.BeginUpdate();
                grdControlService.DataSource = list;
                grdControlService.EndUpdate();
            }
            catch (Exception ex)
            {
                LogSystem.Error(ex);
            }
        }

