        private void SetDefaultCboPTTTGroup(V_HIS_SERE_SERV_5 sereServ)
        {
            try
            {
                if (sereServ == null || cbbPtttGroup.EditValue != null)
                {
                    return;
                }
                cbbPtttGroup.Enabled = true;
                txtPtttGroupCode.Enabled = true;
                if (!sereServ.EKIP_ID.HasValue)
                {
                    long num = 0L;
                    long num2 = 0L;
                    V_HIS_SERVICE surgMisuService = lstService.FirstOrDefault((V_HIS_SERVICE o) => o.ID == sereServ.SERVICE_ID);
                    if (surgMisuService != null)
                    {
                        if (surgMisuService.PTTT_GROUP_ID.HasValue)
                        {
                            HIS_PTTT_GROUP val = BackendDataWorker.Get<HIS_PTTT_GROUP>().FirstOrDefault((HIS_PTTT_GROUP o) => o.ID == surgMisuService.PTTT_GROUP_ID);
                            num = val.ID;
                            txtPtttGroupCode.Text = val.PTTT_GROUP_CODE;
                        }
                        if (surgMisuService.PTTT_METHOD_ID.HasValue)
                        {
                            HIS_PTTT_METHOD val2 = BackendDataWorker.Get<HIS_PTTT_METHOD>().FirstOrDefault((HIS_PTTT_METHOD o) => o.ID == surgMisuService.PTTT_METHOD_ID);
                            num2 = val2.ID;
                            txtMethodCode.Text = val2.PTTT_METHOD_CODE;
                        }
                    }
                    if (num2 > 0)
                    {
                        cboMethod.EditValue = num2;
                    }
                    if (num > 0)
                    {
                        cbbPtttGroup.EditValue = num;
                        if (HisConfigKeys.CheckPermissonOption == "2" && serviceReq.SERVICE_REQ_TYPE_ID == 10)
                        {
                            cbbPtttGroup.Enabled = true;
                            txtPtttGroupCode.Enabled = true;
                        }
                        else
                        {
                            cbbPtttGroup.Enabled = false;
                            txtPtttGroupCode.Enabled = false;
                        }
                    }
                }
                else
                {
                    if (hisSereServPttt == null)
                    {
                        return;
                    }
                    V_HIS_SERVICE surgService = lstService.FirstOrDefault((V_HIS_SERVICE o) => o.ID == sereServ.SERVICE_ID);
                    if (surgService != null && surgService.PTTT_GROUP_ID.HasValue)
                    {
                        HIS_PTTT_GROUP val3 = BackendDataWorker.Get<HIS_PTTT_GROUP>().FirstOrDefault((HIS_PTTT_GROUP o) => o.ID == surgService.PTTT_GROUP_ID);
                        cbbPtttGroup.EditValue = val3.ID;
                        txtPtttGroupCode.Text = val3.PTTT_GROUP_CODE;
                        cbbPtttGroup.Enabled = false;
                        txtPtttGroupCode.Enabled = false;
                    }
                }
            }
            catch (Exception ex)
            {
                LogSystem.Warn(ex);
            }
        }

