        private bool CheckStartTimeFinishTime()
        {
            bool flag = true;
            try
            {
                List<string> list = new List<string>();
                if (dtStart.EditValue != null || dtFinish.EditValue != null)
                {
                    long num = ((dtStart.EditValue != null) ? Parse.ToInt64(dtStart.DateTime.ToString("yyyyMMddHHmm") + "00") : 0);
                    long num2 = ((dtFinish.EditValue != null) ? Parse.ToInt64(dtFinish.DateTime.ToString("yyyyMMddHHmm") + "00") : 0);
                    if (vhisTreatment != null && num < vhisTreatment.IN_TIME)
                    {
                        list.Add(string.Format(ResourceMessage.ThoiGianBatDauThoiGianVaoVien));
                        flag = false;
                    }
                    if (vhisTreatment != null && num > vhisTreatment.OUT_TIME)
                    {
                        list.Add(string.Format(ResourceMessage.ThoiGianBatDauThoiGianRaVien));
                        flag = false;
                    }
                    if (num2 > 0 && num > num2)
                    {
                        list.Add(string.Format(ResourceMessage.ThoiGianBatDauThoiGianKetThuc));
                        flag = false;
                    }
                    if (vhisTreatment != null && num2 < vhisTreatment.IN_TIME)
                    {
                        list.Add(string.Format(ResourceMessage.ThoiGianKetThucThoiGianVaoVien));
                        flag = false;
                    }
                    if (vhisTreatment != null && num2 > vhisTreatment.OUT_TIME)
                    {
                        list.Add(string.Format(ResourceMessage.ThoiGianKetThucThoiGianRaVien));
                        flag = false;
                    }
                    if (!flag && list != null && list.Count > 0)
                    {
                        MessageBox.Show(string.Join("\r\n", list));
                    }
                }
            }
            catch (Exception ex)
            {
                flag = false;
                LogSystem.Warn(ex);
            }
            return flag;
        }

        private bool ValidStartDatePTTT(ref HisSurgServiceReqUpdateListSDO hisSurgResultSDO)
        {
            bool result = true;
            try
            {
                DateTime? dateTime = Inventec.Common.DateTime.Convert.TimeNumberToSystemDateTime(serviceReq.INTRUCTION_TIME);
                if (dtStart.EditValue != null && dateTime.HasValue && long.Parse(dateTime.Value.ToString("yyyyMMddHHmm")) > long.Parse(dtStart.DateTime.ToString("yyyyMMddHHmm")))
                {
                    XtraMessageBox.Show(ResourceMessage.ThoiGianBatDauPhaiLonHonThoiGianYLenh, HIS.Desktop.LibraryMessage.MessageUtil.GetMessage((LibraryMessage.Message.Enum)8), MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
                    result = false;
                }
                if (dtFinish.EditValue != null && dateTime.HasValue && long.Parse(dateTime.Value.ToString("yyyyMMddHHmm")) > long.Parse(dtFinish.DateTime.ToString("yyyyMMddHHmm")))
                {
                    XtraMessageBox.Show(ResourceMessage.ThoiGianKetThucKhongDuocNhoHonThoiGianYLenh, HIS.Desktop.LibraryMessage.MessageUtil.GetMessage((LibraryMessage.Message.Enum)8), MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
                    result = false;
                }
            }
            catch (Exception ex)
            {
                result = true;
                LogSystem.Warn(ex);
            }
            return result;
        }

