        private bool CheckExistFinishTime()
        {
            //IL_0022: Unknown result type (might be due to invalid IL or missing references)
            //IL_0028: Expected O, but got Unknown
            //IL_0062: Unknown result type (might be due to invalid IL or missing references)
            //IL_0068: Expected O, but got Unknown
            //IL_0049: Unknown result type (might be due to invalid IL or missing references)
            //IL_0050: Expected O, but got Unknown
            bool result = true;
            try
            {
                if (dtFinish.EditValue == null)
                {
                    result = false;
                }
                string text = "";
                CommonParam val = new CommonParam();
                if (this.ModuleControls == null || this.ModuleControls.Count == 0)
                {
                    ModuleControlProcess val2 = new ModuleControlProcess(true);
                    this.ModuleControls = val2.GetControls((Control)(object)this, (List<ModuleControlADO>)null, (ModuleControlADO)null);
                }
                GetMessageErrorControlInvalidProcess val3 = new GetMessageErrorControlInvalidProcess();
                val3.Run(this, dxValidationProvider1, this.ModuleControls, val);
                text = val.GetMessage();
                if (!string.IsNullOrEmpty(text))
                {
                    MessageBox.Show(text, HIS.Desktop.LibraryMessage.MessageUtil.GetMessage((LibraryMessage.Message.Enum)7), MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
                }
            }
            catch (Exception ex)
            {
                LogSystem.Warn(ex);
            }
            return result;
        }

        private void reloadSereServ(object data)
        {
            try
            {
                HIS_SERE_SERV sereServResult = (HIS_SERE_SERV)((data is HIS_SERE_SERV) ? data : null);
                if (sereServResult == null)
                {
                    return;
                }
                foreach (V_HIS_SERE_SERV_5 sereServbyServiceReq in sereServbyServiceReqs)
                {
                    if (sereServbyServiceReq.ID == sereServResult.ID)
                    {
                        V_HIS_SERVICE val = lstService.FirstOrDefault((V_HIS_SERVICE o) => o.ID == sereServResult.SERVICE_ID);
                        if (val != null)
                        {
                            sereServbyServiceReq.TDL_SERVICE_CODE = val.SERVICE_CODE;
                            sereServbyServiceReq.TDL_SERVICE_NAME = val.SERVICE_NAME;
